module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire feed,  
    output reg timeout  
);  
    parameter TIMEOUT_PERIOD = 10;  
    reg [3:0] counter; // 4-bit counter to count clock cycles  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout <= 0;  
        end else if (feed) begin  
            counter <= 0;  
            timeout <= 0;  
        end else begin  
            if (counter < TIMEOUT_PERIOD - 1)  
                counter <= counter + 1;  
            else  
                timeout <= 1;  
        end  
    end  
endmodule

