module fractional_n_pll (
    input wire clk_ref,
    input wire [7:0] control_word,
    output reg clk_out,
    output reg locked
);
    reg [15:0] counter;
    reg [7:0] target;

    always @(posedge clk_ref) begin
        counter <= counter + 1;
        if (counter >= (control_word * 100)) begin
            clk_out <= ~clk_out;
            counter <= 0;
            locked <= 1;
        end
    end

    initial begin
        counter = 0;
        clk_out = 0;
        locked = 0;
        target = 0;
    end
endmodule

