module lfsr_5bit (  
    input clk,  
    input reset,  
    input [4:0] seed,  
    output reg [4:0] lfsr_out  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            lfsr_out <= seed;  
