module adaptive_lms_filter (
    input clk,
    input reset,
    input [15:0] x,       // input signal
    input [15:0] d,       // desired signal
    output reg [15:0] y,   // output signal
    output reg [15:0] w0,   // coefficient for tap 0
    output reg [15:0] w1,   // coefficient for tap 1
    output reg [15:0] w2    // coefficient for tap 2
);
    reg [15:0] x_delayed [0:1]; // delay elements for input signal
    reg [15:0] error; // error signal
    parameter mu = 16'd1; // step size

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            w0 <= 16'd0;
            w1 <= 16'd0;
            w2 <= 16'd0;
            y <= 16'd0;
            x_delayed[0] <= 16'd0;
            x_delayed[1] <= 16'd0;
        end else begin
            // Shift input signals
            x_delayed[1] <= x_delayed[0];
            x_delayed[0] <= x;

            // Calculate output
            y <= (w0 * x_delayed[0]) + (w1 * x_delayed[1]) + (w2 * x);

            // Calculate error
            error <= d - y;

            // Update weights using LMS algorithm
            w0 <= w0 + (mu * error * x_delayed[0]);
            w1 <= w1 + (mu * error * x_delayed[1]);
            w2 <= w2 + (mu * error * x);
        end
    end
endmodule

