module pll_4x (  
    input wire clk_in,  
    input wire reset,  
    output reg clk_out  
);  
    reg [1:0] phase;  
    reg [1:0] counter;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            phase <= 2'b00;  
            counter <= 2'b00;  
            clk_out <= 0;  
        end  
        else begin  
            counter <= counter + 1;  
            if (counter == 2'b11) begin  
                clk_out <= ~clk_out;  
                phase <= phase + 1;  
                counter <= 2'b00;  
            end  
        end  
    end  
endmodule

