module fir_filter (
    input wire [7:0] x,            // 8-bit input signal
    input wire clk,                // Clock signal
    output reg [7:0] y             // 8-bit output signal
);
    reg [7:0] coeff [0:7];         // Coefficients for the FIR filter
    reg [7:0] shift_reg [0:7];     // Shift register for storing input samples
    integer i;

    initial begin
        // Initialize filter coefficients
        coeff[0] = 8'h01;
        coeff[1] = 8'h02;
        coeff[2] = 8'h03;
        coeff[3] = 8'h04;
        coeff[4] = 8'h05;
        coeff[5] = 8'h06;
        coeff[6] = 8'h07;
        coeff[7] = 8'h08;
    end

    always @(posedge clk) begin
        // Shift input samples
        shift_reg[0] <= x;
        for (i = 1; i < 8; i = i + 1) begin
            shift_reg[i] <= shift_reg[i-1];
        end

        // Calculate output
        y <= 0; // Clear output before summation
        for (i = 0; i < 8; i = i + 1) begin
            y <= y + (shift_reg[i] * coeff[i]);
        end
    end
endmodule

