module iir_filter (
    input wire clk,
    input wire rst,
    input wire [15:0] x,         // Input signal
    output reg [15:0] y          // Output signal
);

    // Filter coefficients (example values)
    parameter [15:0] b0 = 16'h0010, b1 = 16'h0020, b2 = 16'h0030, b3 = 16'h0040;
    parameter [15:0] a1 = 16'hFFAA, a2 = 16'hFFBB, a3 = 16'hFFCC;

    reg [15:0] x_reg [0:3];      // Input history
    reg [15:0] y_reg [0:3];      // Output history

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y <= 16'b0;
            x_reg[0] <= 16'b0;
            x_reg[1] <= 16'b0;
            x_reg[2] <= 16'b0;
            x_reg[3] <= 16'b0;
            y_reg[0] <= 16'b0;
            y_reg[1] <= 16'b0;
            y_reg[2] <= 16'b0;
            y_reg[3] <= 16'b0;
        end else begin
            // Shift input history
            x_reg[3] <= x_reg[2];
            x_reg[2] <= x_reg[1];
            x_reg[1] <= x_reg[0];
            x_reg[0] <= x;

            // Calculate output using the IIR filter formula
            y <= b0*x_reg[0] + b1*x_reg[1] + b2*x_reg[2] + b3*x_reg[3] 
                 - a1*y_reg[1] - a2*y_reg[2] - a3*y_reg[3];

            // Shift output history
            y_reg[3] <= y_reg[2];
            y_reg[2] <= y_reg[1];
            y_reg[1] <= y_reg[0];
            y_reg[0] <= y;
        end
    end
endmodule

