module AStarPathfinder(  
    input clk,  
    input reset,  
    input [4:0] current_x,  
    input [4:0] current_y,  
    input [4:0] goal_x,  
    input [4:0] goal_y,  
    input [4:0] grid, // simulated grid of obstacles  
    output reg [4:0] next_x,  
    output reg [4:0] next_y  
);  
    // Parameters for grid size  
    parameter GRID_SIZE = 5;  
    reg [4:0] open_set [0:GRID_SIZE*GRID_SIZE];  
    reg [4:0] closed_set [0:GRID_SIZE*GRID_SIZE];  
    integer open_count;  
    integer closed_count;  

    integer i;  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            open_count <= 0;  
            closed_count <= 0;  
            next_x <= 0;  
            next_y <= 0;  
        end else begin  
            // Implementing A* search algorithm  
            // Here you would include logic to process open_set and closed_set,  
            // calculate costs and determine next_x and next_y based on  
            // the A* algorithm. This is a placeholder for your actual logic.  
            // For simplicity, let's just increment the current position towards the goal.  
            if (current_x < goal_x)  
                next_x <= current_x + 1;  
            else if (current_x > goal_x)  
                next_x <= current_x - 1;  
            else  
                next_x <= current_x;  

            if (current_y < goal_y)  
                next_y <= current_y + 1;  
            else if (current_y > goal_y)  
