module iir_filter (
    input clk,
    input reset,
    input [15:0] x, // input sample
    output reg [15:0] y // output filtered sample
);
    // Coefficients for the 4th-order IIR filter (example values)
    parameter [15:0] b0 = 16'h0001, b1 = 16'h0002, b2 = 16'h0003, b3 = 16'h0004;
    parameter [15:0] a1 = 16'h0001, a2 = 16'h0002, a3 = 16'h0003;

    reg [15:0] x_delay[0:3]; // delay line for input samples
    reg [15:0] y_delay[0:2]; // delay line for output samples

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 16'h0000;
            x_delay[0] <= 16'h0000;
            x_delay[1] <= 16'h0000;
            x_delay[2] <= 16'h0000;
            x_delay[3] <= 16'h0000;
            y_delay[0] <= 16'h0000;
            y_delay[1] <= 16'h0000;
        end else begin
            // Shift input samples
            x_delay[3] <= x_delay[2];
            x_delay[2] <= x_delay[1];
            x_delay[1] <= x_delay[0];
            x_delay[0] <= x;

            // Shift output samples
            y_delay[1] <= y_delay[0];
            y_delay[0] <= y;

            // Calculate the output sample using the IIR filter equation
            y <= (b0 * x_delay[0] + b1 * x_delay[1] + b2 * x_delay[2] + b3 * x_delay[3] -
                  a1 * y_delay[0] - a2 * y_delay[1]) >> 16; // Divide by 2^16
        end
    end
endmodule

