module dfs_tree(input clk,  
                input reset,  
                input start,  
                input [3:0] node,  
                output reg [15:0] traversal_order,  
                output reg done);  

  reg [3:0] stack [0:15];  
  reg [3:0] stack_pointer;  
  reg [3:0] current_node;  
  reg [15:0] visited;  

  initial begin  
    stack_pointer = 0;  
    current_node = 0;  
    visited = 0;  
    traversal_order = 0;  
    done = 0;  
  end  

  always @(posedge clk or posedge reset) begin  
    if (reset) begin  
      stack_pointer <= 0;  
      current_node <= 0;  
      visited <= 0;  
      traversal_order <= 0;  
      done <= 0;  
    end else if (start) begin  
      if (stack_pointer < 15) begin  
        stack[stack_pointer] <= node;  
        stack_pointer <= stack_pointer + 1;  
      end else begin  
        current_node <= stack[stack_pointer - 1];  
        stack_pointer <= stack_pointer - 1;  
        if (!visited[current_node]) begin  
          visited[current_node] <= 1;  
          traversal_order <= {traversal_order[11:0], current_node};  
        end  
      end  
    end else if (stack_pointer == 0) begin  
      done <= 1;  
    end  
  end  
endmodule

