module uart_transmitter (
    input wire clk,               // Clock input
    input wire start,             // Start signal
    input wire [7:0] data_in,     // 8-bit data input
    output reg tx,                // Transmitted serial output
    output reg tx_complete        // Transmission complete signal
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 16000000;
    parameter BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] state;              // State machine state
    reg [3:0] bit_count;          // Bit count for data transmission
    reg [15:0] clk_count;         // Clock count for baud rate timing
    reg transmitting;             // Transmitting flag

    // State encoding
    localparam IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;

    always @(posedge clk) begin
        if (transmitting) begin
            if (clk_count < BIT_PERIOD - 1) begin
                clk_count <= clk_count + 1;
                tx <= (state == START_BIT) ? 0 : (state == DATA_BITS) ? data_in[bit_count] : 1;
            end else begin
                clk_count <= 0;
                case (state)
                    IDLE: if (start) begin
                        transmitting <= 1;
                        state <= START_BIT;
                        bit_count <= 0;
                        tx_complete <= 0;
                    end
                    START_BIT: begin
                        state <= DATA_BITS;
                    end
                    DATA_BITS: begin
                        if (bit_count < 7) begin
                            bit_count <= bit_count + 1;
                        end else begin
                            state <= STOP_BIT;
                        end
                    end
                    STOP_BIT: begin
                        transmitting <= 0;
                        tx_complete <= 1;
                        state <= IDLE;
                    end
                endcase
            end
        end else begin
            tx <= 1; // Idle state of the line is high
        end
    end
endmodule

