module fractional_n_pll(
    input wire clk_ref,
    input wire [7:0] fractional,
    input wire reset,
    output reg clk_out
);
    reg [15:0] phase_accumulator;
    reg [7:0] loop_filter_output;
    reg [7:0] divider;
    reg clk_divided;

    always @(posedge clk_ref or posedge reset) begin
        if (reset) begin
            phase_accumulator <= 16'b0;
            loop_filter_output <= 8'b0;
            divider <= 8'b0;
            clk_out <= 0;
            clk_divided <= 0;
        end else begin
            phase_accumulator <= phase_accumulator + fractional;
            if (phase_accumulator >= 16'hFFFF) begin
                phase_accumulator <= phase_accumulator - 16'hFFFF;
                loop_filter_output <= loop_filter_output + 1;
            end
            divider <= loop_filter_output / 2; // Simple loop filter
            clk_divided <= clk_divided + 1;
            if (clk_divided >= divider) begin
                clk_out <= ~clk_out;
                clk_divided <= 0;
            end
        end
    end
endmodule

