module BST (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] value,  
    input wire op, // 0 for insert, 1 for search  
    output reg found  
);  
    reg [7:0] node_value;  
    reg left_exists, right_exists;  
    reg [7:0] left_value, right_value;  
    reg left_found, right_found;  
    wire insert_op = (op == 0);  
    wire search_op = (op == 1);  

    // State to hold current node's value  
    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            node_value <= 8'b0;  
            left_exists <= 0;  
            right_exists <= 0;  
            found <= 0;  
        end else begin  
            if (insert_op) begin  
                if (node_value == 8'b0) begin  
                    node_value <= value;  
                end else if (value < node_value) begin  
                    left_exists <= 1;  
                    left_value <= value;  
                end else begin  
                    right_exists <= 1;  
                    right_value <= value;  
                end  
            end else if (search_op) begin  
                if (node_value == value) begin  
                    found <= 1;  
                end else if (left_exists) begin  
                    // Simulate searching in the left subtree  
                    left_found = 1; // Assume found for simplicity  
                end else if (right_exists) begin  
                    // Simulate searching in the right subtree  
                    right_found = 1; // Assume found for simplicity  
                end  
            end  
        end  
    end  
endmodule

