module sample_rate_converter (
    input clk,
    input reset,
    input [1:0] in_sample,
    output reg [2:0] out_sample
);

    reg [1:0] sample_reg;
    reg [1:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out_sample <= 3'b000;
            count <= 2'b00;
        end else begin
            if (count == 2'b00) begin
                sample_reg <= in_sample;
                out_sample <= {in_sample, 1'b0}; // Produce first output sample
                count <= count + 2'b01;
            end else if (count == 2'b01) begin
                out_sample <= {sample_reg, 1'b0}; // Produce second output sample
                count <= 2'b00; // Reset count for next input sample
            end
        end
    end
endmodule

