module PLL (  
    input wire clk_in,  
    input wire reset,  
    input wire control,  
    output reg clk_out  
);  
    reg [1:0] phase;  
    reg clk_feedback;  
    reg [1:0] loop_filter;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            clk_out <= 0;  
            phase <= 0;  
            loop_filter <= 0;  
            clk_feedback <= 0;  
        end else begin  
            phase <= phase + (control ? 1 : 0);  
            loop_filter <= (loop_filter + phase) >> 1;  
            clk_feedback <= ~clk_feedback;  
            clk_out <= loop_filter[0];  
        end  
    end  
endmodule

