module switching_regulator_controller(  
    input clk,  
    input rst,  
    input [7:0] v_ref,        // Reference voltage  
    input [7:0] v_out,       // Measured output voltage  
    output reg pwm_out        // PWM output signal  
);  
    reg [7:0] duty_cycle;  
    reg [15:0] counter;  
    parameter MAX_COUNT = 16'd10000; // For 1 kHz PWM frequency with 100 MHz clock  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            duty_cycle <= 8'd0;  
            pwm_out <= 0;  
        end else begin  
            if (counter < MAX_COUNT) begin  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
                if (v_out < v_ref) begin  
                    duty_cycle <= duty_cycle + 1;  
                end else if (v_out > v_ref) begin  
                    duty_cycle <= duty_cycle - 1;  
                end  
            end  

            if (counter < duty_cycle * (MAX_COUNT / 256))  
                pwm_out <= 1;  
            else  
                pwm_out <= 0;  
        end  
    end  
endmodule

