module sample_rate_converter #(parameter INPUT_RATE = 1, parameter OUTPUT_RATE = 2)  
(  
    input clk,  
    input rst,  
    input [7:0] in_sample,  
    output reg [7:0] out_sample  
);  
    reg [$clog2(OUTPUT_RATE)-1:0] counter;  
    reg sample_ready;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            out_sample <= 0;  
            sample_ready <= 0;  
        end else begin  
            if (counter == (INPUT_RATE * OUTPUT_RATE) - 1) begin  
                out_sample <= in_sample;  
                sample_ready <= 1;  
                counter <= 0;  
            end else begin  
                sample_ready <= 0;  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

