module phase_detector (  
    input wire clk_a,  
    input wire clk_b,  
    input wire rst,  
    output reg [1:0] phase_out  
);  
    reg [1:0] state, next_state;  
    parameter IDLE = 2'b00, A_LEADING = 2'b01, B_LEADING = 2'b10;  

    always @(posedge clk_a or posedge rst) begin  
        if (rst)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                if (clk_a && !clk_b)  
                    next_state = A_LEADING;  
                else if (!clk_a && clk_b)  
                    next_state = B_LEADING;  
                else  
                    next_state = IDLE;  
            end  
            A_LEADING: begin  
                if (clk_a && !clk_b)  
                    next_state = A_LEADING;  
                else if (!clk_a && clk_b)  
                    next_state = B_LEADING;  
                else  
                    next_state = IDLE;  
            end  
            B_LEADING: begin  
                if (!clk_a && clk_b)  
                    next_state = B_LEADING;  
                else if (clk_a && !clk_b)  
                    next_state = A_LEADING;  
                else  
                    next_state = IDLE;  
            end  
            default: next_state = IDLE;  
        endcase  
    end  

    always @(state) begin  
        case (state)  
            IDLE: phase_out = 2'b00;  
            A_LEADING: phase_out = 2'b01;  
            B_LEADING: phase_out = 2'b10;  
            default: phase_out = 2'b00;  
        endcase  
    end  
endmodule

